insert into qa_memory_learning_outbox(
    job_id, run_id, session_id, workspace_id, user_id, application_id, agent_id,
    selected_model_id, status, attempts, available_at, claimed_by, lease_until,
    last_error_code, created_at, updated_at
) values (
    #{jobId}, #{runId}, #{sessionId}, #{workspaceId}, #{userId}, #{applicationId}, #{agentId},
    #{selectedModelId}, #{status}, #{attempts}, #{availableAt}, #{claimedBy}, #{leaseUntil},
    #{lastErrorCode}, #{createdAt}, #{updatedAt}
) on conflict (run_id) do nothing

mapper.update:
update qa_memory_learning_outbox set status = 'PROCESSING', claimed_by = #{workerId},
    lease_until = #{leaseUntil}, updated_at = #{now}
where job_id = #{jobId} and available_at <= #{now}
  and (status = 'PENDING' or (status = 'PROCESSING' and lease_until < #{now}))

update qa_memory_learning_outbox set status = 'COMPLETED', claimed_by = null, lease_until = null,
    last_error_code = null, updated_at = #{now}
where job_id = #{jobId} and status = 'PROCESSING' and claimed_by = #{workerId}

update qa_memory_learning_outbox set
    status = case when attempts + 1 >= #{maxAttempts} then 'DEAD' else 'PENDING' end,
    attempts = attempts + 1, available_at = #{availableAt}, claimed_by = null, lease_until = null,
    last_error_code = #{errorCode}, updated_at = #{now}
where job_id = #{jobId} and status = 'PROCESSING' and claimed_by = #{workerId}

